"""Build claims.json for the Exotel lane (account-free teardown, 2026-10-20).
Grading rule used in this lane:
  observed      = we saw it: a captured page/doc/code line, DNS answer, bundle string, status JSON, or a count we computed.
                  A documented API object or parameter counts as observed (the doc is the interface).
  vendor-claimed= a capability, performance or stack statement made by Exotel (docs, blog, newsroom) that we did not
                  verify by capture or measurement.
  inferred      = reasoned from cited observations (named in the claim).
  unknown       = not found in public material.
Usage: python3 -I build_claims.py <out_json>"""
import json, sys

D = "data/teardown/exotel/"
R = "research/2026-10-20/teardown/exotel/"
OLD = "research/2026-10-17/lanes/"
DATE = "2026-10-20"
C = []


def c(dim, claim, grade, *ev):
    C.append({"id": f"EXO-{len(C)+1:02d}", "dimension": dim, "claim": claim, "grade": grade, "evidence": list(ev), "date": DATE})


